# owner: platform
import unittest
from datetime import date

from rosterkit.models import Mark, Student
from rosterkit.notices import build_notice

PUPIL = Student("s1", "Lee", "Ann", "A")


def _mark(day, status, who="s1"):
    return Mark(who, date(2024, 3, day), status)


class NoticeTests(unittest.TestCase):
    def test_lists_sorted_absences(self):
        marks = [
            _mark(5, "absent"),
            _mark(4, "present"),
            _mark(1, "absent"),
        ]
        self.assertEqual(
            build_notice(PUPIL, marks),
            "Ann Lee missed 2 day(s): "
            "2024-03-01, 2024-03-05.",
        )

    def test_other_student_rejected(self):
        marks = [_mark(1, "absent"), _mark(2, "absent", "s2")]
        with self.assertRaises(ValueError):
            build_notice(PUPIL, marks)

    def test_no_absences_rejected(self):
        with self.assertRaises(ValueError):
            build_notice(PUPIL, [_mark(1, "late")])


if __name__ == "__main__":
    unittest.main()
